func writeJSONFile(path string, v interface{}) error {
	data, err := json.MarshalIndent(v, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	return writeBytes(path, data)
}

func jsonRawInt64(v int64) json.RawMessage {
	return json.RawMessage(strconv.FormatInt(v, 10))
}

func jsonRawFloat64(v float64) json.RawMessage {
	if math.IsNaN(v) || math.IsInf(v, 0) {
		return json.RawMessage("null")
	}
	b, err := json.Marshal(v)
	if err != nil {
		return json.RawMessage("null")
	}
	return b
}

func jsonRawNull() json.RawMessage {
	return json.RawMessage("null")
}

type orderedJSONMap struct {
	keys   []string
	values map[string]string
}

func newOrderedJSONMap(keys []string, row []string) orderedJSONMap {
	m := orderedJSONMap{keys: append([]string(nil), keys...), values: make(map[string]string, len(keys))}
	for i, k := range keys {
		if i < len(row) {
			m.values[k] = row[i]
		} else {
			m.values[k] = ""
		}
	}
	return m
}

func (m orderedJSONMap) MarshalJSON() ([]byte, error) {
	var buf bytes.Buffer
	buf.WriteByte('{')
	for i, k := range m.keys {
		if i > 0 {
			buf.WriteByte(',')
		}
		kb, err := json.Marshal(k)
		if err != nil {
			return nil, err
		}
		buf.Write(kb)
		buf.WriteByte(':')
		vb, err := json.Marshal(m.values[k])
		if err != nil {
			return nil, err
		}
		buf.Write(vb)
	}
	buf.WriteByte('}')
	return buf.Bytes(), nil
}
