package main

import (
	"encoding/json"
	"math"
	"sort"
	"strconv"
	"strings"
	"time"
)

type profileOutput struct {
	RowCount     int                      `json:"row_count"`
	Columns      []map[string]interface{} `json:"columns"`
	Correlations []map[string]interface{} `json:"correlations"`
}

func runProfile(input, output string) error {
	ds, err := ReadCSV(input)
	if err != nil {
		return err
	}
	return writeJSONFile(output, buildProfile(ds))
}

func buildProfile(ds *Dataset) *profileOutput {
	header := ds.Header
	rows := ds.Rows
	rowCount := len(rows)
	colCount := len(header)
	columns := make([]map[string]interface{}, 0, colCount)

	colNonEmpty := make([][]string, colCount)
	colTypes := make([]string, colCount)
	colFloats := make([][]float64, colCount)
	colInts := make([][]int64, colCount)
	colTimes := make([][]time.Time, colCount)

	for ci, name := range header {
		for _, row := range rows {
			val := ""
			if ci < len(row) {
				val = row[ci]
			}
			if val != "" {
				colNonEmpty[ci] = append(colNonEmpty[ci], val)
			}
		}
		colTypes[ci] = inferProfileType(colNonEmpty[ci])
		switch colTypes[ci] {
		case "int":
			for _, s := range colNonEmpty[ci] {
				v, _ := strconv.ParseInt(s, 10, 64)
				colInts[ci] = append(colInts[ci], v)
				colFloats[ci] = append(colFloats[ci], float64(v))
			}
		case "float":
			for _, s := range colNonEmpty[ci] {
				v, _ := strconv.ParseFloat(s, 64)
				colFloats[ci] = append(colFloats[ci], v)
			}
		case "datetime":
			for _, s := range colNonEmpty[ci] {
				t, _ := time.Parse(time.RFC3339, s)
				colTimes[ci] = append(colTimes[ci], t)
			}
		}
		columns = append(columns, buildColumnProfile(name, colTypes[ci], colNonEmpty[ci], colInts[ci], colFloats[ci], colTimes[ci], rowCount))
	}

	correlations := buildCorrelations(header, colTypes, colFloats, rows)
	return &profileOutput{
		RowCount:     rowCount,
		Columns:      columns,
		Correlations: correlations,
	}
}

func inferProfileType(values []string) string {
	if len(values) == 0 {
		return "string"
	}
	allInt := true
	for _, s := range values {
		if _, err := strconv.ParseInt(s, 10, 64); err != nil {
			allInt = false
			break
		}
	}
	if allInt {
		return "int"
	}
	allFloat := true
	for _, s := range values {
		if _, err := strconv.ParseFloat(s, 64); err != nil {
			allFloat = false
			break
		}
	}
	if allFloat {
		return "float"
	}
	allTime := true
	for _, s := range values {
		if _, err := time.Parse(time.RFC3339, s); err != nil {
			allTime = false
			break
		}
	}
	if allTime {
		return "datetime"
	}
	return "string"
}

func buildColumnProfile(name, colType string, nonEmpty []string, ints []int64, floats []float64, times []time.Time, rowCount int) map[string]interface{} {
	count := len(nonEmpty)
	unique := countUniqueStrings(nonEmpty)
	m := map[string]interface{}{
		"name":       name,
		"type":       colType,
		"count":      count,
		"null_count": rowCount - count,
		"unique":     unique,
	}
	switch colType {
	case "int":
		addNumericProfile(m, colType, floats, count)
		if count == 0 {
			m["mode"] = jsonRawNull()
		} else {
			mode, ok := modeInt(ints)
			if ok {
				m["mode"] = jsonRawInt64(mode)
			} else {
				m["mode"] = jsonRawNull()
			}
		}
	case "float":
		addNumericProfile(m, colType, floats, count)
		if count == 0 {
			m["mode"] = jsonRawNull()
		} else {
			mode, ok := modeFloat(floats)
			if ok {
				m["mode"] = jsonRawFloat64(mode)
			} else {
				m["mode"] = jsonRawNull()
			}
		}
	case "string":
		addStringProfile(m, nonEmpty)
	case "datetime":
		addDatetimeProfile(m, times)
	}
	return m
}

func addNumericProfile(m map[string]interface{}, colType string, vals []float64, count int) {
	if count == 0 {
		m["min"] = jsonRawNull()
		m["max"] = jsonRawNull()
		m["mean"] = jsonRawNull()
		m["stddev"] = jsonRawNull()
		m["median"] = jsonRawNull()
		m["p25"] = jsonRawNull()
		m["p75"] = jsonRawNull()
		m["skewness"] = jsonRawNull()
		m["kurtosis"] = jsonRawNull()
		m["histogram"] = []interface{}{}
		return
	}
	sorted := sortedFloat64s(vals)
	mn := sorted[0]
	mx := sorted[len(sorted)-1]
	mean := meanFloat64s(vals)
	stddev := populationStddevFloat64s(vals, mean)
	median := percentileSorted(sorted, 50)
	p25 := percentileSorted(sorted, 25)
	p75 := percentileSorted(sorted, 75)

	if colType == "int" {
		m["min"] = jsonRawInt64(int64(mn))
		m["max"] = jsonRawInt64(int64(mx))
	} else {
		m["min"] = jsonRawFloat64(mn)
		m["max"] = jsonRawFloat64(mx)
	}
	m["mean"] = jsonRawFloat64(mean)
	m["stddev"] = jsonRawFloat64(stddev)
	m["median"] = jsonRawFloat64(median)
	m["p25"] = jsonRawFloat64(p25)
	m["p75"] = jsonRawFloat64(p75)

	s := sampleStddevFloat64s(vals, mean)
	if count < 3 || s == 0 {
		m["skewness"] = jsonRawNull()
	} else {
		sum := 0.0
		for _, v := range vals {
			z := (v - mean) / s
			sum += z * z * z
		}
		skew := float64(count) / float64((count-1)*(count-2)) * sum
		m["skewness"] = jsonRawFloat64(skew)
	}
	if count < 4 || s == 0 {
		m["kurtosis"] = jsonRawNull()
	} else {
		sum := 0.0
		for _, v := range vals {
			z := (v - mean) / s
			sum += z * z * z * z
		}
		kur := float64(count*(count+1))/float64((count-1)*(count-2)*(count-3))*sum - float64(3*(count-1)*(count-1))/float64((count-2)*(count-3))
		m["kurtosis"] = jsonRawFloat64(kur)
	}
	m["histogram"] = buildHistogram(colType, sorted, mn, mx, count)
}

func buildHistogram(colType string, sorted []float64, mn, mx float64, count int) []interface{} {
	if count == 0 {
		return []interface{}{}
	}
	if mn == mx {
		return []interface{}{
			map[string]interface{}{
				"low":   jsonRawNumber(colType, mn),
				"high":  jsonRawNumber(colType, mx),
				"count": count,
			},
		}
	}
	width := (mx - mn) / 10
	bins := make([]interface{}, 10)
	counts := make([]int, 10)
	for _, v := range sorted {
		idx := int(math.Floor((v - mn) / width))
		if idx < 0 {
			idx = 0
		}
		if idx > 9 {
			idx = 9
		}
		counts[idx]++
	}
	for i := 0; i < 10; i++ {
		low := mn + float64(i)*width
		high := mn + float64(i+1)*width
		if i == 9 {
			high = mx
		}
		bins[i] = map[string]interface{}{
			"low":   jsonRawNumber(colType, low),
			"high":  jsonRawNumber(colType, high),
			"count": counts[i],
		}
	}
	return bins
}

func addStringProfile(m map[string]interface{}, nonEmpty []string) {
	count := len(nonEmpty)
	if count == 0 {
		m["min_length"] = 0
		m["max_length"] = 0
		m["most_common"] = []interface{}{}
		m["avg_length"] = 0
		return
	}
	minLen := len(nonEmpty[0])
	maxLen := len(nonEmpty[0])
	sumLen := 0
	freq := map[string]int{}
	for _, s := range nonEmpty {
		l := len(s)
		if l < minLen {
			minLen = l
		}
		if l > maxLen {
			maxLen = l
		}
		sumLen += l
		freq[s]++
	}
	type kv struct {
		value string
		count int
	}
	pairs := make([]kv, 0, len(freq))
	for k, v := range freq {
		pairs = append(pairs, kv{k, v})
	}
	sort.Slice(pairs, func(i, j int) bool {
		if pairs[i].count != pairs[j].count {
			return pairs[i].count > pairs[j].count
		}
		return pairs[i].value < pairs[j].value
	})
	top := 5
	if len(pairs) < top {
		top = len(pairs)
	}
	mostCommon := make([]interface{}, 0, top)
	for i := 0; i < top; i++ {
		mostCommon = append(mostCommon, map[string]interface{}{
			"value": pairs[i].value,
			"count": pairs[i].count,
		})
	}
	m["min_length"] = minLen
	m["max_length"] = maxLen
	m["most_common"] = mostCommon
	m["avg_length"] = jsonRawFloat64(float64(sumLen) / float64(count))
}

func addDatetimeProfile(m map[string]interface{}, times []time.Time) {
	if len(times) == 0 {
		m["earliest"] = ""
		m["latest"] = ""
		return
	}
	min := times[0]
	max := times[0]
	for _, t := range times[1:] {
		if t.Before(min) {
			min = t
		}
		if t.After(max) {
			max = t
		}
	}
	m["earliest"] = min.Format(time.RFC3339)
	m["latest"] = max.Format(time.RFC3339)
}

func buildCorrelations(header []string, colTypes []string, colFloats [][]float64, rows [][]string) []map[string]interface{} {
	numericIdx := make([]int, 0)
	for i, t := range colTypes {
		if t == "int" || t == "float" {
			numericIdx = append(numericIdx, i)
		}
	}
	if len(numericIdx) < 2 {
		return []map[string]interface{}{}
	}
	out := make([]map[string]interface{}, 0)
	for a := 0; a < len(numericIdx); a++ {
		for b := a + 1; b < len(numericIdx); b++ {
			ai := numericIdx[a]
			bi := numericIdx[b]
			var xs, ys []float64
			for _, row := range rows {
				av := ""
				bv := ""
				if ai < len(row) {
					av = row[ai]
				}
				if bi < len(row) {
					bv = row[bi]
				}
				if av == "" || bv == "" {
					continue
				}
				af, errA := strconv.ParseFloat(av, 64)
				bf, errB := strconv.ParseFloat(bv, 64)
				if errA == nil && errB == nil {
					xs = append(xs, af)
					ys = append(ys, bf)
				}
			}
			corr := correlationFloat64(xs, ys)
			entry := map[string]interface{}{
				"column_a": header[ai],
				"column_b": header[bi],
			}
			if math.IsNaN(corr) {
				entry["correlation"] = jsonRawNull()
			} else {
				entry["correlation"] = jsonRawFloat64(corr)
			}
			out = append(out, entry)
		}
	}
	return out
}

func correlationFloat64(xs, ys []float64) float64 {
	n := len(xs)
	if n < 2 || n != len(ys) {
		return math.NaN()
	}
	meanA := meanFloat64s(xs)
	meanB := meanFloat64s(ys)
	num := 0.0
	sumA := 0.0
	sumB := 0.0
	for i := 0; i < n; i++ {
		da := xs[i] - meanA
		db := ys[i] - meanB
		num += da * db
		sumA += da * da
		sumB += db * db
	}
	denom := math.Sqrt(sumA * sumB)
	if denom == 0 {
		return math.NaN()
	}
	return num / denom
}

func countUniqueStrings(values []string) int {
	seen := map[string]struct{}{}
	for _, v := range values {
		seen[v] = struct{}{}
	}
	return len(seen)
}

func modeInt(vals []int64) (int64, bool) {
	freq := map[int64]int{}
	for _, v := range vals {
		freq[v]++
	}
	if len(freq) == len(vals) {
		return 0, false
	}
	maxCount := 0
	var best int64
	first := true
	for v, c := range freq {
		if c > maxCount || (c == maxCount && (first || v < best)) {
			maxCount = c
			best = v
			first = false
		}
	}
	return best, true
}

func modeFloat(vals []float64) (float64, bool) {
	freq := map[float64]int{}
	for _, v := range vals {
		freq[v]++
	}
	if len(freq) == len(vals) {
		return 0, false
	}
	maxCount := 0
	best := 0.0
	first := true
	for v, c := range freq {
		if c > maxCount || (c == maxCount && (first || v < best)) {
			maxCount = c
			best = v
			first = false
		}
	}
	return best, true
}

func jsonRawNumber(colType string, f float64) json.RawMessage {
	if math.IsNaN(f) || math.IsInf(f, 0) {
		return jsonRawNull()
	}
	if colType == "int" && f == math.Trunc(f) && f >= -9223372036854775808 && f <= 9223372036854775807 {
		return jsonRawInt64(int64(f))
	}
	return jsonRawFloat64(f)
}
