package main

import (
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"
)

type compareChange struct {
	Type string                 `json:"type"`
	Key  map[string]string      `json:"key"`
	Row  map[string]string      `json:"row,omitempty"`
	Left map[string]string      `json:"left,omitempty"`
	Right map[string]string     `json:"right,omitempty"`
	Diff []string               `json:"diff,omitempty"`
}

type compareOutput struct {
	Summary compareSummary `json:"summary"`
	Changes []compareChange `json:"changes"`
}

type compareSummary struct {
	LeftRows   int `json:"left_rows"`
	RightRows  int `json:"right_rows"`
	Added      int `json:"added"`
	Removed    int `json:"removed"`
	Modified   int `json:"modified"`
	Unchanged  int `json:"unchanged"`
}

func runCompare(leftPath, rightPath, keyArg, outputPath string, tolerance float64, ignoreCols []string) error {
	left, err := ReadCSV(leftPath)
	if err != nil {
		return err
	}
	right, err := ReadCSV(rightPath)
	if err != nil {
		return err
	}
	if !sameStrings(left.Header, right.Header) {
		return fmt.Errorf("ERROR: schema mismatch: headers differ")
	}
	header := left.Header
	keys := splitCSVList(keyArg)
	for _, k := range keys {
		if indexOf(header, k) < 0 {
			return fmt.Errorf("ERROR: invalid key: column %s not found", k)
		}
	}
	for _, c := range ignoreCols {
		if indexOf(header, c) < 0 {
			return fmt.Errorf("ERROR: invalid ignore: column %s not found", c)
		}
	}

	ignoreSet := map[string]struct{}{}
	for _, c := range ignoreCols {
		ignoreSet[c] = struct{}{}
	}
	keySet := map[string]struct{}{}
	for _, k := range keys {
		keySet[k] = struct{}{}
	}

	leftRows := buildKeyedRows(left, keys)
	rightRows := buildKeyedRows(right, keys)

	added, removed, modified, unchanged := 0, 0, 0, 0
	changes := []compareChange{}

	for k, rrow := range rightRows {
		if _, ok := leftRows[k]; !ok {
			added++
			changes = append(changes, compareChange{
				Type: "added",
				Key:  keyMap(keys, rrow),
				Row:  rowMap(header, rrow),
			})
		}
	}
	for k, lrow := range leftRows {
		rrow, ok := rightRows[k]
		if !ok {
			removed++
			changes = append(changes, compareChange{
				Type: "removed",
				Key:  keyMap(keys, lrow),
				Row:  rowMap(header, lrow),
			})
			continue
		}
		diff := diffColumns(header, lrow, rrow, keySet, ignoreSet, tolerance)
		if len(diff) > 0 {
			modified++
			changes = append(changes, compareChange{
				Type:  "modified",
				Key:   keyMap(keys, lrow),
				Left:  rowMap(header, lrow),
				Right: rowMap(header, rrow),
				Diff:  diff,
			})
		} else {
			unchanged++
		}
	}

	sort.SliceStable(changes, func(i, j int) bool {
		ti := changeTypeOrder(changes[i].Type)
		tj := changeTypeOrder(changes[j].Type)
		if ti != tj {
			return ti < tj
		}
		return joinKey(keys, changes[i].Key) < joinKey(keys, changes[j].Key)
	})

	out := compareOutput{
		Summary: compareSummary{
			LeftRows:  len(left.Rows),
			RightRows: len(right.Rows),
			Added:     added,
			Removed:   removed,
			Modified:  modified,
			Unchanged: unchanged,
		},
		Changes: changes,
	}
	return writeJSONFile(outputPath, out)
}

type keyedRow struct {
	key string
	row []string
}

func buildKeyedRows(ds *Dataset, keys []string) map[string]keyedRow {
	idxs := make([]int, len(keys))
	for i, k := range keys {
		idxs[i] = indexOf(ds.Header, k)
	}
	out := map[string]keyedRow{}
	for _, row := range ds.Rows {
		parts := make([]string, len(keys))
		for i, idx := range idxs {
			if idx < len(row) {
				parts[i] = row[idx]
			} else {
				parts[i] = ""
			}
		}
		k := strings.Join(parts, "\x00")
		if _, exists := out[k]; !exists {
			out[k] = keyedRow{key: k, row: row}
		}
	}
	return out
}

func diffColumns(header []string, left, right []string, keySet, ignoreSet map[string]struct{}, tolerance float64) []string {
	diff := []string{}
	for i, col := range header {
		if _, isKey := keySet[col]; isKey {
			continue
		}
		if _, ignored := ignoreSet[col]; ignored {
			continue
		}
		lv := cellAt(left, i)
		rv := cellAt(right, i)
		if !equalWithTolerance(lv, rv, tolerance) {
			diff = append(diff, col)
		}
	}
	return diff
}

func equalWithTolerance(a, b string, tolerance float64) bool {
	af, aerr := strconv.ParseFloat(a, 64)
	bf, berr := strconv.ParseFloat(b, 64)
	if aerr == nil && berr == nil {
		return math.Abs(af-bf) <= tolerance
	}
	return a == b
}

func keyMap(keys []string, row []string) map[string]string {
	m := map[string]string{}
	for _, k := range keys {
		idx := indexOf(keys, k)
		if idx >= 0 && idx < len(row) {
			m[k] = row[idx]
		} else {
			m[k] = ""
		}
	}
	return m
}

func rowMap(header []string, row []string) map[string]string {
	m := map[string]string{}
	for i, h := range header {
