func fillLinear(ds *Dataset, cols []string) (*Dataset, error) {
    rows := make([][]string, len(ds.Rows))
    for i, row := range ds.Rows {
        rows[i] = append([]string(nil), row...)
    }
    for _, c := range cols {
        idx := indexOf(ds.Header, c)
        if idx < 0 {
            continue
        }
        numeric := make([]float64, len(rows))
        okNum := make([]bool, len(rows))
        for i, row := range rows {
            if idx < len(row) && row[idx] != "" {
                if f, err := strconv.ParseFloat(row[idx], 64); err == nil {
                    numeric[i] = f
                    okNum[i] = true
                }
            }
        }
        for i := range rows {
            if idx < len(rows[i]) && rows[i][idx] != "" {
                continue
            }
            var lo = -1
            for j := i - 1; j >= 0; j-- {
                if okNum[j] {
                    lo = j
                    break
                }
            }
            var hi = -1
            for j := i + 1; j < len(rows); j++ {
                if okNum[j] {
                    hi = j
                    break
                }
            }
            if lo >= 0 && hi >= 0 {
                val := numeric[lo] + (numeric[hi]-numeric[lo])*float64(i-lo)/float64(hi-lo)
                for len(rows[i]) <= idx {
                    rows[i] = append(rows[i], "")
                }
                rows[i][idx] = strconv.FormatFloat(val, 'f', -1, 64)
            }
        }
    }
