    }
    return &Dataset{Header: header, Rows: rows}, nil
}

type aggregationSpec struct {
    Column   string
    Function string
    As       string
}

func recipeAggregations(step map[string]interface{}) ([]aggregationSpec, error) {
    raw, ok := step["aggregations"]
    if !ok {
        return nil, fmt.Errorf("ERROR: invalid recipe: aggregations required")
    }
    arr, ok := raw.([]interface{})
    if !ok {
        return nil, fmt.Errorf("ERROR: invalid recipe: aggregations must be array")
    }
    out := make([]aggregationSpec, 0, len(arr))
    for _, item := range arr {
        m, ok := item.(map[string]interface{})
        if !ok {
            return nil, fmt.Errorf("ERROR: invalid recipe: aggregation must be object")
        }
        out = append(out, aggregationSpec{
            Column:   recipeString(m, "column"),
            Function: recipeString(m, "function"),
            As:        recipeString(m, "as"),
        })
    }
    return out, nil
}

func aggregateValue(rows [][]string, header []string, a aggregationSpec) string {
    idx := indexOf(header, a.Column)
    nums := []float64{}
    nonEmpty := 0
    for _, row := range rows {
        if idx >= 0 && idx < len(row) && row[idx] != "" {
            nonEmpty++
            if f, err := strconv.ParseFloat(row[idx], 64); err == nil {
                nums = append(nums, f)
            }
        }
    }
    switch a.Function {
    case "count":
        return strconv.Itoa(nonEmpty)
    case "sum":
        sum := 0.0
        for _, f := range nums {
            sum += f
        }
        return formatFloat(sum)
    case "avg":
        if len(nums) == 0 {
            return "NaN"
        }
        return formatFloat(meanFloat64s(nums))
    case "min":
        if len(nums) == 0 {
            return "NaN"
        }
        return formatFloat(minFloat64s(sortedFloat64s(nums)))
    case "max":
        if len(nums) == 0 {
            return "NaN"
        }
        return formatFloat(maxFloat64s(sortedFloat64s(nums)))
    default:
        return ""
    }
}

func transformSort(ds *Dataset, step map[string]interface{}) (*Dataset, error) {
    cols := recipeStringList(step, "columns")
    if len(cols) == 0 {
        cols = ds.Header
    }
    if err := validateColumns(ds, cols); err != nil {
        return nil, err
    }
    order := recipeString(step, "order")
    desc := order == "desc" || order == "descending" || recipeBool(step, "descending", false)
    idxs := make([]int, len(cols))
    for i, c := range cols {
        idxs[i] = indexOf(ds.Header, c)
    }
    rows := make([][]string, len(ds.Rows))
    copy(rows, ds.Rows)
    sort.SliceStable(rows, func(i, j int) bool {
        for _, idx := range idxs {
            a := cellAt(rows[i], idx)
            b := cellAt(rows[j], idx)
            af, aerr := strconv.ParseFloat(a, 64)
            bf, berr := strconv.ParseFloat(b, 64)
            var cmp int
            if aerr == nil && berr == nil {
                if af < bf {
                    cmp = -1
                } else if af > bf {
                    cmp = 1
                }
            } else {
                cmp = strings.Compare(a, b)
            }
            if cmp != 0 {
                if desc {
                    return cmp > 0
                }
                return cmp < 0
            }
        }
        return false
    })
    return &Dataset{Header: ds.Header, Rows: rows}, nil
}

func transformFilter(ds *Dataset, step map[string]interface{}) (*Dataset, error) {
    exprStr := recipeString(step, "expression")
    if exprStr == "" {
        return nil, fmt.Errorf("ERROR: invalid recipe: filter requires expression")
    }
    expr, err := parseExpr(exprStr)
    if err != nil {
