}

func transformSelect(ds *Dataset, step map[string]interface{}) (*Dataset, error) {
    cols := recipeStringList(step, "columns")
    if err := validateColumns(ds, cols); err != nil {
        return nil, err
    }
    idxs := make([]int, len(cols))
    for i, c := range cols {
        idxs[i] = indexOf(ds.Header, c)
    }
    rows := make([][]string, len(ds.Rows))
    for i, row := range ds.Rows {
        out := make([]string, len(cols))
        for j, idx := range idxs {
            out[j] = cellAt(row, idx)
        }
        rows[i] = out
    }
    return &Dataset{Header: cols, Rows: rows}, nil
}

func transformRename(ds *Dataset, step map[string]interface{}) (*Dataset, error) {
    col := recipeString(step, "column")
    to := recipeString(step, "to")
    if col == "" || to == "" {
        return nil, fmt.Errorf("ERROR: invalid recipe: rename requires column and to")
    }
    idx := indexOf(ds.Header, col)
    if idx < 0 {
        return nil, fmt.Errorf("ERROR: invalid recipe: column %s not found", col)
    }
    header := append([]string(nil), ds.Header...)
    header[idx] = to
    return &Dataset{Header: header, Rows: ds.Rows}, nil
}

func transformDeduplicate(ds *Dataset, step map[string]interface{}) (*Dataset, error) {
    cols := recipeStringList(step, "columns")
    if len(cols) == 0 {
        cols = ds.Header
    }
    if err := validateColumns(ds, cols); err != nil {
        return nil, err
    }
    keep := recipeString(step, "keep")
    if keep == "" {
        keep = "first"
    }
    idxs := make([]int, len(cols))
    for i, c := range cols {
        idxs[i] = indexOf(ds.Header, c)
    }
    if keep == "last" {
        last := map[string]int{}
        for i, row := range ds.Rows {
            last[groupKeyByIdx(idxs, row)] = i
        }
        rows := [][]string{}
        for i, row := range ds.Rows {
            if last[groupKeyByIdx(idxs, row)] == i {
                rows = append(rows, append([]string(nil), row...))
            }
        }
        return &Dataset{Header: ds.Header, Rows: rows}, nil
    }
    seen := map[string]bool{}
    rows := [][]string{}
    for _, row := range ds.Rows {
        k := groupKeyByIdx(idxs, row)
        if !seen[k] {
            seen[k] = true
            rows = append(rows, append([]string(nil), row...))
        }
    }
    return &Dataset{Header: ds.Header, Rows: rows}, nil
}

func transformSplit(ds *Dataset, step map[string]interface{}) (*Dataset, error) {
    col := recipeString(step, "column")
    if col == "" {
        return nil, fmt.Errorf("ERROR: invalid recipe: split requires column")
    }
    idx := indexOf(ds.Header, col)
    if idx < 0 {
        return nil, fmt.Errorf("ERROR: invalid recipe: column %s not found", col)
    }
    delimiter := recipeString(step, "delimiter")
    names := recipeStringList(step, "names")
    if len(names) == 0 {
        return nil, fmt.Errorf("ERROR: invalid recipe: split requires names")
    }
    header := make([]string, 0, len(ds.Header)-1+len(names))
    header = append(header, ds.Header[:idx]...)
    header = append(header, names...)
    header = append(header, ds.Header[idx+1:]...)
    rows := make([][]string, len(ds.Rows))
    for i, row := range ds.Rows {
        val := cellAt(row, idx)
        parts := strings.Split(val, delimiter)
        mapped := make([]string, len(names))
        for j := 0; j < len(names); j++ {
            if j < len(parts) {
                if j == len(names)-1 && len(parts) > len(names) {
                    mapped[j] = strings.Join(parts[j:], delimiter)
                } else {
                    mapped[j] = parts[j]
                }
            }
        }
        out := make([]string, 0, len(header))
        out = append(out, row[:idx]...)
        out = append(out, mapped...)
        out = append(out, row[idx+1:]...)
        rows[i] = out
    }
    return &Dataset{Header: header, Rows: rows}, nil
}

func transformAssert(ds *Dataset, step map[string]interface{}) (*Dataset, error) {
    exprStr := recipeString(step, "expression")
    if exprStr == "" {
        return nil, fmt.Errorf("ERROR: invalid recipe: assert requires expression")
    }
    expr, err := parseExpr(exprStr)
    if err != nil {
        return nil, fmt.Errorf("ERROR: invalid recipe: %v", err)
    }
    msg := recipeString(step, "message")
    for i, row := range ds.Rows {
        v, err := evalExpressionRow(expr, ds.Header, row)
        if err != nil || math.IsNaN(v) || v <= 0 {
            return nil, fmt.Errorf("ERROR: assertion failed on row %d: %s", i+1, msg)
        }
    }
    return ds, nil
}

func transformNormalize(ds *Dataset, step map[string]interface{}) (*Dataset, error) {
    col := recipeString(step, "column")
    if col == "" {
        return nil, fmt.Errorf("ERROR: invalid recipe: normalize requires column")
    }
    idx := indexOf(ds.Header, col)
    if idx < 0 {
        return nil, fmt.Errorf("ERROR: invalid recipe: column %s not found", col)
    }
    method := recipeString(step, "method")
    as := recipeString(step, "as")
    if as == "" {
        return nil, fmt.Errorf("ERROR: invalid recipe: normalize requires as")
    }
    nums := []float64{}
    for _, row := range ds.Rows {
        s := cellAt(row, idx)
        if s != "" {
            if f, err := strconv.ParseFloat(s, 64); err == nil {
                nums = append(nums, f)
            }
        }
    }
    header := append([]string(nil), ds.Header...)
    header = append(header, as)
    rows := make([][]string, len(ds.Rows))
    for i, row := range ds.Rows {
        out := append([]string(nil), row...)
        for len(out) < len(header) {
            out = append(out, "")
        }
        s := cellAt(row, idx)
        if s == "" {
            out[len(header)-1] = ""
            rows[i] = out
            continue
        }
        f, err := strconv.ParseFloat(s, 64)
        if err != nil {
            out[len(header)-1] = ""
            rows[i] = out
            continue
        }
        var val float64
        switch method {
        case "zscore":
            mean := meanFloat64s(nums)
            sd := populationStddevFloat64s(nums, mean)
            if sd == 0 {
                val = 0
            } else {
                val = (f - mean) / sd
            }
        case "minmax":
            mn := minFloat64s(sortedFloat64s(nums))
            mx := maxFloat64s(sortedFloat64s(nums))
            if mx == mn {
                val = 0
            } else {
                val = (f - mn) / (mx - mn)
            }
        default:
            return nil, fmt.Errorf("ERROR: invalid recipe: unknown normalize method %s", method)
        }
        out[len(header)-1] = strconv.FormatFloat(val, 'f', -1, 64)
        rows[i] = out
    }
    return &Dataset{Header: header, Rows: rows}, nil
}

func transformEncode(ds *Dataset, step map[string]interface{}) (*Dataset, error) {
    col := recipeString(step, "column")
    if col == "" {
        return nil, fmt.Errorf("ERROR: invalid recipe: encode requires column")
    }
    idx := indexOf(ds.Header, col)
    if idx < 0 {
        return nil, fmt.Errorf("ERROR: invalid recipe: column %s not found", col)
    }
    method := recipeString(step, "method")
    drop := recipeBool(step, "drop", false)
    unique := []string{}
    seen := map[string]bool{}
    for _, row := range ds.Rows {
        s := cellAt(row, idx)
        if s != "" && !seen[s] {
            seen[s] = true
            unique = append(unique, s)
        }
    }
    sort.Strings(unique)
    switch method {
    case "onehot":
        newCols := make([]string, len(unique))
        for i, v := range unique {
            newCols[i] = col + "_" + v
        }
        var header []string
        if drop {
            header = make([]string, 0, len(ds.Header)-1+len(newCols))
            header = append(header, ds.Header[:idx]...)
            header = append(header, newCols...)
            header = append(header, ds.Header[idx+1:]...)
        } else {
            header = append([]string(nil), ds.Header...)
            header = append(header, newCols...)
        }
        rows := make([][]string, len(ds.Rows))
        for i, row := range ds.Rows {
            val := cellAt(row, idx)
            out := []string{}
            if drop {
                out = append(out, row[:idx]...)
            } else {
                out = append(out, row...)
            }
            for _, v := range unique {
                if val == v {
                    out = append(out, "1")
                } else {
                    out = append(out, "0")
                }
            }
            if drop {
                out = append(out, row[idx+1:]...)
            }
            rows[i] = out
        }
        return &Dataset{Header: header, Rows: rows}, nil
    case "ordinal":
        as := recipeString(step, "as")
        if as == "" {
            return nil, fmt.Errorf("ERROR: invalid recipe: ordinal encode requires as")
        }
        ranks := map[string]string{}
        for i, v := range unique {
            ranks[v] = strconv.Itoa(i)
        }
        header := append([]string(nil), ds.Header...)
        header = append(header, as)
        rows := make([][]string, len(ds.Rows))
        for i, row := range ds.Rows {
            out := append([]string(nil), row...)
            val := cellAt(row, idx)
            if val != "" {
                out = append(out, ranks[val])
            } else {
                out = append(out, "")
            }
            rows[i] = out
        }
        return &Dataset{Header: header, Rows: rows}, nil
    default:
        return nil, fmt.Errorf("ERROR: invalid recipe: unknown encode method %s", method)
    }
}

func transformRollup(ds *Dataset, step map[string]interface{}) (*Dataset, error) {
    groupCols := recipeStringList(step, "columns")
    if err := validateColumns(ds, groupCols); err != nil {
        return nil, err
    }
    aggs, err := recipeAggregations(step)
    if err != nil {
        return nil, err
    }
    for _, a := range aggs {
        if indexOf(ds.Header, a.Column) < 0 {
            return nil, fmt.Errorf("ERROR: invalid recipe: column %s not found", a.Column)
        }
    }
    header := append([]string(nil), groupCols...)
    for _, a := range aggs {
        header = append(header, a.As)
    }
    rows := [][]string{}
    detailGroups := map[string][][]string{}
    detailOrder := []string{}
    for _, row := range ds.Rows {
        key := groupKey(ds.Header, groupCols, row)
        if _, ok := detailGroups[key]; !ok {
            detailOrder = append(detailOrder, key)
        }
        detailGroups[key] = append(detailGroups[key], append([]string(nil), row...))
    }
    sort.Strings(detailOrder)
    for _, key := range detailOrder {
        vals := decodeGroupKey(key)
        out := append([]string(nil), vals...)
        for _, a := range aggs {
            out = append(out, aggregateValue(detailGroups[key], ds.Header, a))
        }
        rows = append(rows, out)
    }
    for k := len(groupCols) - 1; k >= 1; k-- {
        subGroups := map[string][][]string{}
        subOrder := []string{}
        for _, key := range detailOrder {
            vals := decodeGroupKey(key)
            subKey := strings.Join(vals[:k], "\x00")
            if _, ok := subGroups[subKey]; !ok {
                subOrder = append(subOrder, subKey)
            }
            subGroups[subKey] = append(subGroups[subKey], detailGroups[key]...)
        }
        sort.Strings(subOrder)
        for _, key := range subOrder {
            vals := strings.Split(key, "\x00")
            out := make([]string, len(groupCols))
            copy(out, vals)
            for j := k; j < len(groupCols); j++ {
                out[j] = "*"
            }
            for _, a := range aggs {
                out = append(out, aggregateValue(subGroups[key], ds.Header, a))
            }
            rows = append(rows, out)
        }
    }
    total := []string{}
    for range groupCols {
        total = append(total, "*")
    }
    for _, a := range aggs {
        total = append(total, aggregateValue(ds.Rows, ds.Header, a))
    }
    rows = append(rows, total)
    return &Dataset{Header: header, Rows: rows}, nil
}

func transformDetect(ds *Dataset, step map[string]interface{}) (*Dataset, error) {
    col := recipeString(step, "column")
    if col == "" {
        return nil, fmt.Errorf("ERROR: invalid recipe: detect requires column")
    }
    idx := indexOf(ds.Header, col)
    if idx < 0 {
        return nil, fmt.Errorf("ERROR: invalid recipe: column %s not found", col)
    }
    method := recipeString(step, "method")
    as := recipeString(step, "as")
    if as == "" {
        return nil, fmt.Errorf("ERROR: invalid recipe: detect requires as")
    }
    factor := recipeFloat(step, "factor", 1.5)
    nums := []float64{}
    for _, row := range ds.Rows {
        s := cellAt(row, idx)
        if s != "" {
            if f, err := strconv.ParseFloat(s, 64); err == nil {
                nums = append(nums, f)
            }
        }
    }
    sortedNums := sortedFloat64s(nums)
    header := append([]string(nil), ds.Header...)
    header = append(header, as)
    rows := make([][]string, len(ds.Rows))
    for i, row := range ds.Rows {
        out := append([]string(nil), row...)
        for len(out) < len(header) {
            out = append(out, "")
        }
        s := cellAt(row, idx)
        if s == "" {
            out[len(header)-1] = "0"
            rows[i] = out
            continue
        }
        f, err := strconv.ParseFloat(s, 64)
        if err != nil {
            out[len(header)-1] = "0"
            rows[i] = out
            continue
        }
        out[len(header)-1] = detectOutlier(method, f, sortedNums, factor)
        rows[i] = out
    }
    return &Dataset{Header: header, Rows: rows}, nil
}

func detectOutlier(method string, v float64, sorted []float64, factor float64) string {
    switch method {
    case "iqr":
        if len(sorted) < 2 {
            return "0"
        }
        q1 := percentileSorted(sorted, 25)
        q3 := percentileSorted(sorted, 75)
        iqr := q3 - q1
        if v < q1-factor*iqr || v > q3+factor*iqr {
            return "1"
        }
        return "0"
    case "zscore":
        if len(sorted) == 0 {
            return "0"
        }
        mean := meanFloat64s(sorted)
        sd := populationStddevFloat64s(sorted, mean)
        if sd == 0 {
            return "0"
        }
        if math.Abs(v-mean)/sd > factor {
            return "1"
        }
        return "0"
    case "mad":
        if len(sorted) == 0 {
            return "0"
        }
        med := percentileSorted(sorted, 50)
        devs := make([]float64, len(sorted))
        for i, x := range sorted {
            devs[i] = math.Abs(x - med)
        }
        mad := percentileSorted(sortedFloat64s(devs), 50)
        if mad == 0 {
            if v == med {
                return "0"
            }
            return "1"
        }
        mz := 0.6745 * (v - med) / mad
        if math.Abs(mz) > factor {
            return "1"
        }
        return "0"
    default:
        return "0"
    }
}

func transformBin(ds *Dataset, step map[string]interface{}) (*Dataset, error) {
    col := recipeString(step, "column")
    if col == "" {
        return nil, fmt.Errorf("ERROR: invalid recipe: bin requires column")
    }
    idx := indexOf(ds.Header, col)
    if idx < 0 {
        return nil, fmt.Errorf("ERROR: invalid recipe: column %s not found", col)
    }
    method := recipeString(step, "method")
    bins := recipeInt(step, "bins", 0)
    if bins <= 0 {
        return nil, fmt.Errorf("ERROR: invalid recipe: bins must be positive")
    }
    as := recipeString(step, "as")
    if as == "" {
        return nil, fmt.Errorf("ERROR: invalid recipe: bin requires as")
    }
    nums := []float64{}
    for _, row := range ds.Rows {
        s := cellAt(row, idx)
        if s != "" {
            if f, err := strconv.ParseFloat(s, 64); err == nil {
                nums = append(nums, f)
            }
        }
    }
    sortedNums := sortedFloat64s(nums)
    header := append([]string(nil), ds.Header...)
    header = append(header, as)
    rows := make([][]string, len(ds.Rows))
    for i, row := range ds.Rows {
        out := append([]string(nil), row...)
        for len(out) < len(header) {
            out = append(out, "")
        }
        s := cellAt(row, idx)
        if s == "" {
            out[len(header)-1] = ""
            rows[i] = out
            continue
        }
        f, err := strconv.ParseFloat(s, 64)
        if err != nil {
            out[len(header)-1] = ""
            rows[i] = out
            continue
        }
        out[len(header)-1] = binLabel(method, f, sortedNums, bins)
        rows[i] = out
    }
    return &Dataset{Header: header, Rows: rows}, nil
}

func binLabel(method string, v float64, sorted []float64, bins int) string {
    if len(sorted) == 0 {
        return ""
    }
    mn := sorted[0]
    mx := sorted[len(sorted)-1]
    if mx == mn {
        return "[" + strconv.FormatFloat(mn, 'f', -1, 64) + "," + strconv.FormatFloat(mx, 'f', -1, 64) + "]"
    }
    switch method {
    case "width":
        w := (mx - mn) / float64(bins)
        i := int(math.Floor((v - mn) / w))
        if i < 0 {
            i = 0
        }
        if i > bins-1 {
            i = bins - 1
        }
        low := mn + float64(i)*w
        high := mn + float64(i+1)*w
        if i == bins-1 {
            high = mx
        }
        return formatBinLabel(low, high, i == bins-1)
    case "quantile":
        bounds := make([]float64, bins+1)
        for j := 0; j <= bins; j++ {
            bounds[j] = percentileSorted(sorted, float64(j*100)/float64(bins))
        }
        i := 0
        for j := 0; j < bins; j++ {
            if v >= bounds[j] {
                i = j
            }
        }
        if v < bounds[0] {
            i = 0
        }
        if v >= bounds[bins] {
            i = bins - 1
        }
        low := bounds[i]
        high := bounds[i+1]
        if i == bins-1 {
            high = mx
        }
        return formatBinLabel(low, high, i == bins-1)
    default:
        return ""
    }
}

func formatBinLabel(low, high float64, last bool) string {
    ls := strconv.FormatFloat(low, 'f', -1, 64)
    hs := strconv.FormatFloat(high, 'f', -1, 64)
    if last {
        return "[" + ls + "," + hs + "]"
    }
    return "[" + ls + "," + hs + ")"
}

func transformHash(ds *Dataset, step map[string]interface{}) (*Dataset, error) {
    cols := recipeStringList(step, "columns")
    if len(cols) == 0 {
        cols = ds.Header
    }
    if err := validateColumns(ds, cols); err != nil {
        return nil, err
    }
    as := recipeString(step, "as")
    if as == "" {
        return nil, fmt.Errorf("ERROR: invalid recipe: hash requires as")
    }
    idxs := make([]int, len(cols))
    for i, c := range cols {
        idxs[i] = indexOf(ds.Header, c)
    }
    header := append([]string(nil), ds.Header...)
    header = append(header, as)
    rows := make([][]string, len(ds.Rows))
    for i, row := range ds.Rows {
        out := append([]string(nil), row...)
        for len(out) < len(header) {
            out = append(out, "")
        }
        var sb strings.Builder
        for j, idx := range idxs {
            if j > 0 {
                sb.WriteByte(0)
            }
            sb.WriteString(cellAt(row, idx))
        }
        sum := sha256.Sum256([]byte(sb.String()))
        out[len(header)-1] = hex.EncodeToString(sum[:])
        rows[i] = out
    }
    return &Dataset{Header: header, Rows: rows}, nil
}

func groupKey(header, cols []string, row []string) string {
    idxs := make([]int, len(cols))
    for i, c := range cols {
        idxs[i] = indexOf(header, c)
    }
    return groupKeyByIdx(idxs, row)
}

func groupKeyByIdx(idxs []int, row []string) string {
    parts := make([]string, len(idxs))
    for i, idx := range idxs {
        parts[i] = cellAt(row, idx)
    }
    return strings.Join(parts, "\x00")
}

func decodeGroupKey(key string) []string {
    return strings.Split(key, "\x00")
